#include "tests/support/socket/append_growth_test_fixture.hpp"
using namespace append_test;
namespace {
void normal(){
    for(unsigned character=0;character<256;++character)for(bool heap:{false,true}){
        Fixture f;f.seed("ABC",heap?31:15);const auto prior=f.value().storage_00;auto& returned=f.character(4,static_cast<std::uint8_t>(character));const auto data=s::receive_buffer_address(f.value());const auto out=f.f.f.memory.view(data,8);
        check(&returned==&f.value()&&f.value().size_10==7&&out[0]=='A'&&out[1]=='B'&&out[2]=='C'&&out[3]==character&&out[4]==0&&out[5]==0xcc&&out[6]==0xcc&&out[7]==0xcc,"012350 all byte values, exactly one character/NUL despite extra4; no implicit fill");
        check(f.f.copy.calls.size()==1&&f.f.copy.calls[0].count==3&&f.f.f.api.allocations.size()==1&&f.f.f.api.frees.size()==unsigned(heap),"012350 always allocate, one old-payload COPY, cached heap branch");
        check(std::equal(prior.begin()+8,prior.end(),f.value().storage_00.begin()+8),"only first8 storage bytes published");
    }
    for(bool character:{false,true})for(std::uint64_t size:{0,1,7,15,16,31,63,4094,4095,8191})for(std::uint64_t spare:{0,8,100})for(std::uint64_t extra:{0,1,7,16,4096}){
        Fixture f;std::string old;for(std::size_t i=0;i<size;++i)old.push_back(static_cast<char>((i*23)&255));const auto oldcap=std::max<std::uint64_t>(15,size+spare);f.seed(old,oldcap);const auto old_data=s::receive_buffer_address(f.value()),source=f.source(extra==7?2:extra),count=extra==7?2:extra;
        const auto prior=f.value().storage_00;const auto capacity=std::max((size+extra)|std::uint64_t{15},oldcap+oldcap/2);
        f.f.copy.before=[&](unsigned){check(f.value().size_10==size+extra&&f.value().capacity_18==capacity&&f.value().storage_00==prior,"size/cap stores precede every COPY; pointer publication last");};
        if(character)f.character(extra,0x81);else f.bytes(extra,source,count);
        const auto data=s::receive_buffer_address(f.value());std::vector<std::uint8_t> expected(capacity+1,0xcc);std::copy(old.begin(),old.end(),expected.begin());if(character){expected[size]=0x81;expected[size+1]=0;}else{std::copy_n(f.external.begin(),count,expected.begin()+size);expected[size+count]=0;}
        const auto actual=f.f.f.memory.view(data,capacity+1);check(std::equal(expected.begin(),expected.end(),actual.begin())&&f.value().size_10==size+extra,"independent full allocation byte oracle; extra differs from actual appended byte count");
        check(data!=old_data&&f.f.f.api.allocations==std::vector<std::uint64_t>{capacity+1+(capacity+1>=4096?39U:0U)}&&f.f.copy.calls.size()==(character?1U:2U),"exact geometric/rounded allocation and helper-specific COPY counts, including zero lengths");
        check(f.f.f.api.frees.size()==unsigned(oldcap>15),"old heap free only and exactly once");
        if(oldcap>15)check(f.f.f.api.frees[0].second==oldcap+1+(oldcap+1>=4096?39U:0U),"old sized free uses cached capacity and4096/+39 threshold");
        if(capacity+1>=4096)check(data%32==0&&buffer_test::word(f.f.f.memory.view(data-8,8))==f.f.f.blocks.back()->raw,"new32-byte alignment and raw allocation header");
        if(!character)check(f.f.copy.calls[0].count==size&&f.f.copy.calls[1].from==source&&f.f.copy.calls[1].count==count,"007e30 ordered old payload then external source; NUL at old+count");
    }
    for(std::uint64_t size:{1,7,15,16,31,63,4095})for(std::uint64_t at:{0,1,3}){
        if(at>size)continue;Fixture f;const auto old=std::string(size,'A')+"";f.seed(old,std::max<std::uint64_t>(15,size));const auto count=std::min<std::uint64_t>(16,size-at+1),source=s::receive_buffer_address(f.value())+at;const auto expected=old+(old+std::string("\0",1)).substr(at,count);f.bytes(count,source,count);check(f.text()==expected&&f.f.copy.calls.size()==2,"self source including original terminator remains live through both COPYs before old free");
    }
    {Fixture f;f.seed("abc",15);auto source=f.source(4);f.bytes(1,source,4);const auto actual=f.f.f.memory.view(s::receive_buffer_address(f.value()),8);check(f.value().size_10==4&&std::equal(f.external.begin(),f.external.begin()+4,actual.begin()+3)&&actual[7]==0,"007e30 count greater than extra remains independent when bounded allocation permits");}
}
void prefixes(){
    for(bool character:{false,true})for(unsigned phase:{1U,2U}){
        if(character&&phase==2)continue;Fixture f;f.seed("abcdef",16);const auto prior=f.value().storage_00;auto source=f.source(40);f.f.copy.before=[&](unsigned n){if(n==phase)throw Failure{9};};rejects<Failure>([&]{if(character)f.character(40,'K');else f.bytes(40,source,40);});check(f.value().size_10==46&&f.value().capacity_18==47&&f.value().storage_00==prior&&f.f.f.api.frees.empty()&&f.f.copy.calls.size()==phase,"COPY failure exposes new metadata and old pointer, no free/publication/rollback");
    }
    for(bool character:{false,true}){
        {Fixture f;f.seed("abcdef",16);const auto prior=f.value();f.f.f.api.on_allocate=[](){throw Failure{9};};rejects<Failure>([&]{if(character)f.character(40,'K');else f.bytes(40,0,40);});check(f.value().storage_00==prior.storage_00&&f.value().size_10==6&&f.value().capacity_18==16,"allocation failure before metadata/COPY");}
        {Fixture f;f.seed("abcdef",16);const auto prior=f.value().storage_00;auto source=f.source(40);f.f.f.api.on_free=[](){throw Failure{9};};rejects<Failure>([&]{if(character)f.character(40,'K');else f.bytes(40,source,40);});check(f.value().storage_00==prior&&f.value().size_10==46&&f.f.copy.calls.size()==(character?1U:2U),"old free exception after payload/NUL prevents pointer publication");}
        {Fixture f;f.seed("abcdef",16);auto source=f.source(40);std::uintptr_t data=0;f.f.copy.after=[&](unsigned n){if(n==1)data=f.f.copy.calls[0].to;};f.f.f.api.on_free=[&](){auto out=f.f.f.memory.view(data+6,2);check(character?(out[0]=='K'&&out[1]==0):f.f.f.memory.view(data+46,1)[0]==0,"tail writes and NUL complete before old free");f.value().storage_00.fill(0);f.value().size_10=77;f.value().capacity_18=88;};if(character)f.character(40,'K');else f.bytes(40,source,40);check(s::receive_buffer_address(f.value())==data&&f.value().size_10==77&&f.value().capacity_18==88,"final first8 pointer publication overrides free callback prefix, metadata remains callback-live");}
        {Fixture f;f.seed("abcdef",16);auto& other=f.f.f.add(17);std::fill(other.bytes.begin(),other.bytes.end(),'Z');const auto pointer=other.raw,source=f.source(40);f.f.f.api.on_allocate=[&](){buffer_test::word(f.value().storage_00,pointer);f.value().capacity_18=15;f.value().size_10=1;};f.f.f.api.on_free=[](){throw Failure{19};};try{if(character)f.character(40,'K');else f.bytes(40,source,40);throw std::runtime_error("expected free exception");}catch(const Failure& e){check(e.code==19&&f.f.copy.calls[0].from==pointer&&f.f.copy.calls[0].count==6&&f.value().size_10==46&&f.value().capacity_18==47,"heap old pointer reloaded after allocation, old count/cap cached, metadata overwrites allocate mutation");}}
        for(bool large:{false,true}){Fixture f;f.seed("abcdef",16);f.f.f.api.null_allocate=true;auto source=f.source(large?5000:40);try{if(character)f.character(large?5000:40,'K');else f.bytes(large?5000:40,source,large?5000:40);throw std::runtime_error("expected null failure");}catch(const b::Terminal& e){check(large&&e.kind==3&&f.value().size_10==6&&f.f.copy.calls.empty(),"aligned NULL terminal before metadata");}catch(const s::UnsupportedInput&){check(!large&&f.value().size_10==46&&f.f.copy.calls.size()==1,"small NULL unchecked until bounded COPY after metadata");}}
        {Fixture f;f.value().size_10=0x7fffffffffffffffULL;try{if(character)f.character(1,0);else f.bytes(1,0,0);throw std::runtime_error("expected length terminal");}catch(const b::Terminal& e){check(e.kind==1&&f.f.f.api.allocations.empty(),"length terminal before allocation");}}
        for(bool capacity_overflow:{false,true}){Fixture f;f.seed("abcdef",15);if(capacity_overflow)f.value().capacity_18=UINT64_MAX;else f.value().size_10=0x7ffffffffffffffeULL;f.f.f.api.on_allocate=[&](){check(f.f.f.api.allocations.back()==0x8000000000000027ULL,"symbolic maximum fallback allocation exact");throw Failure{9};};rejects<Failure>([&]{if(character)f.character(1,0);else f.bytes(1,0,0);});check(f.f.copy.calls.empty(),"symbolic huge input does not really allocate or copy");}
        {Fixture f;f.seed(std::string(4095,'H'),4095);const auto old=s::receive_buffer_address(f.value());buffer_test::word(f.f.f.memory.view(old-8,8),old-40);auto source=f.source(1);try{if(character)f.character(1,'K');else f.bytes(1,source,1);throw std::runtime_error("expected header terminal");}catch(const b::Terminal& e){check(e.kind==3&&f.f.copy.calls.size()==(character?1U:2U)&&f.f.f.api.frees.empty()&&s::receive_buffer_address(f.value())==old,"invalid old header after payload/NUL and before free/final pointer");}}
    }
    {Fixture f;f.seed("ABC",15);std::uintptr_t data=0;f.f.copy.after=[&](unsigned){data=f.f.copy.calls[0].to;auto& region=f.f.f.regions[f.f.f.blocks.back()->region];region.bytes=region.bytes.first(4);};rejects<s::UnsupportedInput>([&]{f.character(1,'K');});check(f.f.f.memory.view(data+3,1)[0]=='K'&&f.value().size_10==4&&f.value().capacity_18==22,"character store visible before separate bounded NUL store failure");}
}
}
int main(){try{normal();prefixes();std::cout<<"PASS: "<<checks<<" socket append growth checks; actual012350/007e30 distinct payload/extra semantics, external/self binary oracle, metadata/copy/tail/free/pointer order and bounded failure prefixes\n";}catch(const std::exception& e){std::cerr<<"FAIL after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}catch(...){std::cerr<<"FAIL: unexpected terminal\n";return 1;}}

